import json
from httpbin.core import app
client = app.test_client()

def test_delete_with_json_body_reflected_in_json_field():
    payload = json.dumps({'key': 'value'})
    r = client.delete(
        '/delete',
        data=payload,
        content_type='application/json'
    )
    assert r.status_code == 200
    body = r.get_json()
    assert body is not None
    assert body['json'] == {'key': 'value'}
    assert body['form'] == {}
    assert body['files'] == {}
    assert isinstance(body['headers'], dict)
    assert 'Content-Type' in body['headers'] or 'content-type' in {k.lower(): v for k, v in body['headers'].items()}

test_delete_with_json_body_reflected_in_json_field()

from httpbin.core import app
client = app.test_client()

def test_delete_with_form_data_reflected_in_form_field():
    r = client.delete(
        '/delete',
        data={'field1': 'val1'},
        content_type='application/x-www-form-urlencoded'
    )
    assert r.status_code == 200
    body = r.get_json()
    assert body is not None
    assert body['form'] == {'field1': 'val1'}
    assert body['json'] is None
    assert body['files'] == {}
    assert body['args'] == {}

test_delete_with_form_data_reflected_in_form_field()
